MonarchFormField(label = {{label}}, helperText = "Value: " + (value?.let { isoFormat.format(Date(it)) } ?: "none")) { controlModifier ->
    FlowRow(
        modifier = controlModifier,
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        itemVerticalAlignment = Alignment.CenterVertically,
    ) {
        MonarchButton(text = date?.let { dateFormat.format(Date(it)) } ?: "Set date", onClick = { pickingDate = true }, leadingIcon = { MonarchIcon(SampleIcons.Calendar, contentDescription = null, size = MonarchIconSize.Sm) })
        MonarchButton(text = timeFormat.format(Date(minutes * 60_000L)), onClick = { pickingTime = true }, leadingIcon = { MonarchIcon(SampleIcons.Clock, contentDescription = null, size = MonarchIconSize.Sm) })
        // The time zone slot: a label here, or a time zone select.
        Text(text = {{timeZone}}, style = MonarchTheme.typography.caption, color = MonarchTheme.colors.textMuted)
    }
}
if (pickingDate) {
    DatePickerDialog(
        onDismissRequest = { pickingDate = false },
        confirmButton = {
            MonarchButton(
                text = "OK",
                onClick = { date = dateState.selectedDateMillis ?: date; pickingDate = false },
                variant = MonarchButtonVariant.Primary,
            )
        },
        dismissButton = {
            MonarchButton(text = "Cancel", onClick = { pickingDate = false }, variant = MonarchButtonVariant.Ghost)
        },
    ) {
        DatePicker(state = dateState)
    }
}
if (pickingTime) {
    var mode by remember { mutableStateOf(TimePickerDisplayMode.Picker) }
    TimePickerDialog(
        onDismissRequest = { pickingTime = false },
        confirmButton = {
            MonarchButton(
                text = "OK",
                onClick = { minutes = timeState.hour * 60 + timeState.minute; pickingTime = false },
                variant = MonarchButtonVariant.Primary,
            )
        },
        title = { TimePickerDialogDefaults.Title(displayMode = mode) },
        dismissButton = {
            MonarchButton(text = "Cancel", onClick = { pickingTime = false }, variant = MonarchButtonVariant.Ghost)
        },
        modeToggleButton = {
            TimePickerDialogDefaults.DisplayModeToggle(
                onDisplayModeChange = { mode = if (mode == TimePickerDisplayMode.Picker) TimePickerDisplayMode.Input else TimePickerDisplayMode.Picker },
                displayMode = mode,
            )
        },
    ) {
        if (mode == TimePickerDisplayMode.Picker) TimePicker(state = timeState) else TimeInput(state = timeState)
    }
}

examples.setupTemplate:
val context = LocalContext.current
var date by remember { mutableStateOf<Long?>({{value|millis}} / 86_400_000L * 86_400_000L) }
var minutes by remember { mutableIntStateOf((({{value|millis}} % 86_400_000L) / 60_000L).toInt()) }
var pickingDate by remember { mutableStateOf(false) }
var pickingTime by remember { mutableStateOf(false) }
val dateState = rememberDatePickerState(
    initialSelectedDateMillis = date,
    selectableDates = object : SelectableDates {
        override fun isSelectableDate(utcTimeMillis: Long): Boolean = utcTimeMillis >= {{min|millis}} / 86_400_000L * 86_400_000L
    },
)
val timeState = rememberTimePickerState(initialHour = minutes / 60, initialMinute = minutes % 60, is24Hour = true)
val dateFormat = remember { DateFormat.getDateInstance(DateFormat.SHORT, Locale.forLanguageTag({{locale}})).apply { timeZone = TimeZone.getTimeZone("UTC") } }
val timeFormat = remember { SimpleDateFormat("HH:mm", Locale.ROOT).apply { timeZone = TimeZone.getTimeZone("UTC") } }
val isoFormat = remember { SimpleDateFormat("yyyy-MM-dd'T'HH:mm", Locale.ROOT).apply { timeZone = TimeZone.getTimeZone("UTC") } }
// The wall-clock value: the day's UTC midnight plus the minutes. Never converted between zones.
val value: Long? = date?.let { it + minutes * 60_000L }

